using System.Runtime.InteropServices;
using System.Runtime.InteropServices.WindowsRuntime;
using Windows.Media.Control;

namespace DeskCanvas.App.Services;

internal enum NowPlayingState { None, Playing, Paused, Stopped, Unknown }
internal enum NowPlayingCommand { Previous, PlayPause, Next, Seek }
internal enum NowPlayingRefreshCause { Media, Playback, Timeline, Reconciliation, Switch, Seek }
internal sealed record NowPlayingSnapshot(bool HasSession,string SourceApp,string Title,string Artist,string Album,byte[]? Artwork,NowPlayingState State,TimeSpan Position,TimeSpan End,bool CanPrevious,bool CanPlayPause,bool CanNext,bool CanSeek,DateTimeOffset ObservedAt=default)
{ internal static NowPlayingSnapshot Empty { get; }=new(false,"","再生中のコンテンツはありません","","",null,NowPlayingState.None,TimeSpan.Zero,TimeSpan.Zero,false,false,false,false); }
internal sealed record NowPlayingData(string? SourceApp,string? Title,string? Artist,string? Album,byte[]? Artwork,NowPlayingState State,TimeSpan Position,TimeSpan End,bool CanPrevious,bool CanPlayPause,bool CanNext,bool CanSeek,DateTimeOffset TimelineObservedAt=default);
internal interface INowPlayingManagerProvider { Task<INowPlayingManager> RequestAsync(); }
internal interface INowPlayingManager:IDisposable { INowPlayingSession? CurrentSession { get; } event EventHandler? CurrentSessionChanged; }
internal interface INowPlayingSession:IDisposable { event EventHandler? MediaPropertiesChanged;event EventHandler? PlaybackInfoChanged;event EventHandler? TimelinePropertiesChanged;Task<NowPlayingData> ReadAsync();Task<bool> TryCommandAsync(NowPlayingCommand command,TimeSpan position=default); }
internal interface IGlobalMediaCommandSender { bool IsAvailable { get; } bool TrySend(NowPlayingCommand command); }
internal interface INowPlayingService:IDisposable { NowPlayingSnapshot Snapshot { get; } event EventHandler<NowPlayingSnapshot>? SnapshotChanged;IDisposable Acquire();Task<bool> PreviousAsync();Task<bool> PlayPauseAsync();Task<bool> NextAsync();Task<bool> SeekAsync(TimeSpan position); }

internal static class NowPlayingTimelineMath
{
 internal static TimeSpan Clamp(TimeSpan position,TimeSpan end)=>end>TimeSpan.Zero?TimeSpan.FromTicks(Math.Clamp(position.Ticks,0,end.Ticks)):position<TimeSpan.Zero?TimeSpan.Zero:position;
 internal static bool IsLoopRewind(TimeSpan projected,TimeSpan raw,TimeSpan end)=>end>TimeSpan.Zero&&projected>=end-TimeSpan.FromSeconds(2)&&raw<=TimeSpan.FromSeconds(3);
 // GSMTC's manager switch and its Media/Playback notifications can carry an old
 // timeline while the same song is still playing.  They are observations, not a
 // user seek, so keep the locally projected clock unless the provider's own
 // timeline event (or a genuine loop) says that a rewind happened.
 internal static bool ShouldKeepProjected(NowPlayingRefreshCause cause,NowPlayingState previousState,TimeSpan projected,TimeSpan raw,TimeSpan end)
  =>previousState==NowPlayingState.Playing&&raw<projected&&cause is not NowPlayingRefreshCause.Timeline and not NowPlayingRefreshCause.Seek&&!IsLoopRewind(projected,raw,end);
}
internal sealed class NowPlayingService:INowPlayingService
{
 private readonly INowPlayingManagerProvider provider;private readonly IGlobalMediaCommandSender mediaCommands;private readonly TimeSpan reconciliationInterval;private readonly SemaphoreSlim gate=new(1,1);private readonly object stateGate=new();private INowPlayingManager? manager;private INowPlayingSession? session;private System.Threading.Timer? reconciliationTimer;private int consumers;private bool disposed;private NowPlayingSnapshot snapshot=NowPlayingSnapshot.Empty;private string? mediaIdentity;private TimeSpan lastKnownEnd,lastKnownPosition;private TimeSpan? pendingSeek;
 internal NowPlayingService():this(new GsmtcManagerProvider()){}
