 public NowPlayingSnapshot Snapshot=>Project(snapshot,DateTimeOffset.UtcNow);public event EventHandler<NowPlayingSnapshot>? SnapshotChanged;
 public IDisposable Acquire(){var connect=false;lock(stateGate){if(disposed)return EmptyLease.Instance;consumers++;connect=consumers==1;}if(connect)_=ConnectAsync();return new Lease(this);}private void Release(){var disconnect=false;lock(stateGate){if(consumers>0)consumers--;disconnect=consumers==0;}if(disconnect)_=DisconnectAsync();}private bool ShouldRun{get{lock(stateGate)return !disposed&&consumers>0;}}
 private async Task ConnectAsync(){await gate.WaitAsync().ConfigureAwait(false);try{if(!ShouldRun||manager is not null)return;INowPlayingManager? next=null;try{next=await provider.RequestAsync().ConfigureAwait(false);if(!ShouldRun){next.Dispose();return;}manager=next;manager.CurrentSessionChanged+=ManagerChanged;await SwitchCoreAsync();}catch{next?.Dispose();manager=null;Clear();}}finally{gate.Release();}}
 private async Task DisconnectAsync(){await gate.WaitAsync().ConfigureAwait(false);try{if(ShouldRun)return;StopReconciliation();DetachSession();if(manager is not null){manager.CurrentSessionChanged-=ManagerChanged;manager.Dispose();manager=null;}Clear();}finally{gate.Release();}}
 private void ManagerChanged(object? _,EventArgs __)=>_ = SwitchAsync();private void MediaChanged(object? _,EventArgs __)=>_ = RefreshAsync(NowPlayingRefreshCause.Media);private void PlaybackChanged(object? _,EventArgs __)=>_ = RefreshAsync(NowPlayingRefreshCause.Playback);private void TimelineChanged(object? _,EventArgs __)=>_ = RefreshAsync(NowPlayingRefreshCause.Timeline);
