 private async Task SwitchCoreAsync(){var next=manager?.CurrentSession;if(ReferenceEquals(next,session)){await RefreshCoreAsync(NowPlayingRefreshCause.Switch);return;}DetachSession();session=next;if(session is null){StopReconciliation();Clear();return;}session.MediaPropertiesChanged+=MediaChanged;session.PlaybackInfoChanged+=PlaybackChanged;session.TimelinePropertiesChanged+=TimelineChanged;StartReconciliation();await RefreshCoreAsync(NowPlayingRefreshCause.Switch);}
