 private async Task RefreshAsync(NowPlayingRefreshCause cause){await gate.WaitAsync().ConfigureAwait(false);try{if(ShouldRun&&session is not null)await RefreshCoreAsync(cause);}catch{/* End and position survive transient read faults. */}finally{gate.Release();}}
 private async Task RefreshCoreAsync(NowPlayingRefreshCause cause){var current=session;if(current is null){Clear();return;}var data=await current.ReadAsync().ConfigureAwait(false);if(!ReferenceEquals(current,session)||!ShouldRun)return;var source=data.SourceApp?.Trim()??"";var title=string.IsNullOrWhiteSpace(data.Title)?"タイトル不明":data.Title.Trim();var artist=data.Artist?.Trim()??"";var album=data.Album?.Trim()??"";var identity=string.Join("\u001f",source,title,artist,album);var now=DateTimeOffset.UtcNow;var rawEnd=data.End>TimeSpan.Zero?data.End:TimeSpan.Zero;var rawPosition=data.Position<TimeSpan.Zero?TimeSpan.Zero:data.Position;var observed=data.TimelineObservedAt!=default&&data.TimelineObservedAt<=now?data.TimelineObservedAt:now;if(data.State==NowPlayingState.Playing&&rawEnd>TimeSpan.Zero&&observed<now)rawPosition+=now-observed;rawPosition=NowPlayingTimelineMath.Clamp(rawPosition,rawEnd);
  var different=!string.Equals(identity,mediaIdentity,StringComparison.Ordinal);if(different){if(mediaIdentity is not null)Clear();mediaIdentity=identity;lastKnownEnd=rawEnd;lastKnownPosition=rawPosition;}var end=rawEnd>TimeSpan.Zero?rawEnd:lastKnownEnd;var projected=Project(snapshot,now).Position;
  if(!different){if(rawEnd>TimeSpan.Zero)lastKnownEnd=rawEnd;if(rawEnd==TimeSpan.Zero&&rawPosition==TimeSpan.Zero&&lastKnownEnd>TimeSpan.Zero)rawPosition=lastKnownPosition;var seek=pendingSeek;var acceptBackward=cause is NowPlayingRefreshCause.Timeline or NowPlayingRefreshCause.Seek||seek.HasValue||NowPlayingTimelineMath.IsLoopRewind(projected,rawPosition,end);if(seek.HasValue){rawPosition=NowPlayingTimelineMath.Clamp(seek.Value,end);pendingSeek=null;}if(NowPlayingTimelineMath.ShouldKeepProjected(cause,snapshot.State,projected,rawPosition,end)&&!acceptBackward)rawPosition=projected;lastKnownPosition=NowPlayingTimelineMath.Clamp(rawPosition,end);}var position=NowPlayingTimelineMath.Clamp(lastKnownPosition,end);Publish(new NowPlayingSnapshot(true,source,title,artist,album,data.Artwork,data.State,position,end,data.CanPrevious||mediaCommands.IsAvailable,data.CanPlayPause,data.CanNext||mediaCommands.IsAvailable,data.CanSeek&&end>TimeSpan.Zero,now));}
