}
internal sealed class WindowsGlobalMediaCommandSender:IGlobalMediaCommandSender{public bool IsAvailable=>OperatingSystem.IsWindows();public bool TrySend(NowPlayingCommand command){var appCommand=command switch{NowPlayingCommand.Previous=>12,NowPlayingCommand.Next=>11,_=>0};if(appCommand==0)return false;try{return PostMessage(new IntPtr(0xffff),0x0319,IntPtr.Zero,new IntPtr(appCommand<<16));}catch{return false;}}[DllImport("user32.dll",SetLastError=true)]private static extern bool PostMessage(IntPtr window,uint message,IntPtr wParam,IntPtr lParam);}
internal sealed class GsmtcManagerProvider:INowPlayingManagerProvider{public async Task<INowPlayingManager> RequestAsync()=>new GsmtcManagerAdapter(await GlobalSystemMediaTransportControlsSessionManager.RequestAsync());}
internal sealed class GsmtcManagerAdapter:INowPlayingManager{private readonly GlobalSystemMediaTransportControlsSessionManager manager;private GlobalSystemMediaTransportControlsSession? native;private GsmtcSessionAdapter? adapter;internal GsmtcManagerAdapter(GlobalSystemMediaTransportControlsSessionManager manager){this.manager=manager;manager.CurrentSessionChanged+=Changed;}public INowPlayingSession? CurrentSession{get{var current=manager.GetCurrentSession();if(ReferenceEquals(current,native))return adapter;native=current;adapter=current is null?null:new GsmtcSessionAdapter(current);return adapter;}}public event EventHandler? CurrentSessionChanged;private void Changed(GlobalSystemMediaTransportControlsSessionManager _,CurrentSessionChangedEventArgs __)=>CurrentSessionChanged?.Invoke(this,EventArgs.Empty);public void Dispose()=>manager.CurrentSessionChanged-=Changed;}
internal sealed class GsmtcSessionAdapter:INowPlayingSession{private readonly GlobalSystemMediaTransportControlsSession session;internal GsmtcSessionAdapter(GlobalSystemMediaTransportControlsSession session){this.session=session;session.MediaPropertiesChanged+=MediaChanged;session.PlaybackInfoChanged+=PlaybackChanged;session.TimelinePropertiesChanged+=TimelineChanged;}public event EventHandler? MediaPropertiesChanged;public event EventHandler? PlaybackInfoChanged;public event EventHandler? TimelinePropertiesChanged;private void MediaChanged(GlobalSystemMediaTransportControlsSession _,MediaPropertiesChangedEventArgs __)=>MediaPropertiesChanged?.Invoke(this,EventArgs.Empty);private void PlaybackChanged(GlobalSystemMediaTransportControlsSession _,PlaybackInfoChangedEventArgs __)=>PlaybackInfoChanged?.Invoke(this,EventArgs.Empty);private void TimelineChanged(GlobalSystemMediaTransportControlsSession _,TimelinePropertiesChangedEventArgs __)=>TimelinePropertiesChanged?.Invoke(this,EventArgs.Empty);public async Task<NowPlayingData> ReadAsync(){var media=await session.TryGetMediaPropertiesAsync();var playback=session.GetPlaybackInfo();var timeline=session.GetTimelineProperties();var controls=playback.Controls;byte[]? art=null;try{if(media.Thumbnail is not null){using var random=await media.Thumbnail.OpenReadAsync();using var input=random.AsStreamForRead();using var output=new MemoryStream();await input.CopyToAsync(output).ConfigureAwait(false);art=output.ToArray();}}catch{}return new NowPlayingData(session.SourceAppUserModelId,media.Title,media.Artist,media.AlbumTitle,art,playback.PlaybackStatus switch{GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing=>NowPlayingState.Playing,GlobalSystemMediaTransportControlsSessionPlaybackStatus.Paused=>NowPlayingState.Paused,GlobalSystemMediaTransportControlsSessionPlaybackStatus.Stopped=>NowPlayingState.Stopped,_=>NowPlayingState.Unknown},timeline.Position,timeline.EndTime,controls.IsPreviousEnabled,controls.IsPlayPauseTog